  ('Royal Enfield', 'Classic 350', null, null, null, 'Battery', 'Battery drain after accessory fitment', 'Riders report weak starts or battery drain after auxiliary lights, louder horns, or phone chargers are wired without a relay and fused lines.', 'medium', '3,000-12,000 km', 5000, null, 'Slow cranking after overnight parking, dimming aux lights at idle, repeated relay clicking', 'Wire accessories through a relay with fused lines and ask for a resting-voltage check (12.4V+) at every service.', 800, 4500, 34, 12, 'medium', 'seed', null, now()),
  ('Royal Enfield', 'Classic 350', null, null, null, 'Chain/Sprocket', 'Chain slack and noise in stop-go city riding', 'Chain noise and frequent adjustment needs show up around dense-traffic use and stretched lubrication intervals.', 'low', '4,000-10,000 km', 5000, null, 'Clunk on throttle on/off, rattle over bumps, slack drifting past 25-30 mm', 'Clean and lube the chain every 500-700 km in city use and keep slack within the manual''s 25-30 mm window.', 300, 1200, 26, 6, 'medium', 'seed', null, now()),
  ('Royal Enfield', 'Classic 350', null, null, null, 'General Ownership', 'Mirror and footpeg buzz near highway cruising revs', 'A busy patch around 4,000-5,500 rpm (roughly 90-100 km/h) is widely discussed; mirrors blur and pegs tingle on longer stints.', 'low', null, null, '4,000-5,500 rpm', 'Blurred mirrors at highway speed, tingling pegs or bars after 30+ minutes', 'Try bar-end weights, keep cruising just below the buzz band, and have engine-mount bolt torque checked at service.', 0, 1500, 41, 9, 'medium', 'seed', null, now()),
  ('Royal Enfield', 'Classic 350', null, null, null, 'Clutch', 'Clutch drag and hard first-gear shifts in traffic', 'Some owners log notchy first-gear engagement and a heavy lever feel in long commutes, easing after cable adjustment and fresh oil.', 'medium', '8,000-15,000 km', 10000, null, 'False neutrals, clunky first-gear engagement, lever effort rising in jams', 'Adjust cable free play, lube the lever pivot, and stick to the manual''s oil grade and change interval.', 300, 2500, 18, 5, 'medium', 'seed', null, now()),
  ('Royal Enfield', 'Classic 350', null, null, null, 'Brake Pads', 'Front disc squeal and early pad glazing in city use', 'Squeal under light braking and glazed pads are commonly reported from brake-dragging city commutes.', 'medium', '8,000-15,000 km', 10000, null, 'Squeal at low-speed braking, longer stopping distances, scoring lines on the disc', 'Inspect pads at every service, avoid resting a finger on the lever in traffic, and keep caliper pins clean.', 600, 6000, 22, 7, 'medium', 'seed', null, now()),
  ('Royal Enfield', 'Classic 350', null, 2021, 2022, 'Electrical', 'Instrument cluster condensation on early J-series', 'Owners of early J-platform builds report fogging inside the speedometer glass after rain or washing; dealers have resealed or replaced clusters.', 'low', '0-15,000 km', null, null, 'Mist inside the cluster glass after rain, erratic fuel-bar readings', 'Park covered in monsoon, avoid pressure-washing the console, and push for a warranty reseal if fogging persists.', 0, 3500, 15, 4, 'low', 'seed', null, now()),
  ('Royal Enfield', 'Classic 350', null, 2021, 2022, 'Engine/Cooling', 'Minor oil weep near head joints reported on early builds', 'A small number of early-build owners report an oil film near head or rocker joints; usually a torque or gasket fix.', 'low', '5,000-20,000 km', null, null, 'Oil film on cooling fins near the head, a drop or two under the bike after long rides', 'Monitor oil level between services and ask the dealer for a torque/gasket check if a weep line appears.', 500, 3000, 12, 3, 'low', 'seed', null, now()),
  ('Royal Enfield', 'Classic 350', null, null, null, 'Tyres', 'Tube-type wheels turn punctures into roadside jobs', 'Spoke rims with tubes mean a puncture usually needs the wheel off and a tube swap rather than a quick plug, a frequent touring complaint.', 'low', 'Any', null, null, 'Sudden full deflation instead of a slow leak, repeated punctures on worn tubes', 'Carry a spare tube and levers on tours, check spoke tension at services, and replace aged tubes with quality ones.', 300, 1500, 20, 5, 'medium', 'seed', null, now()),
  ('Royal Enfield', 'Classic 350', null, null, null, 'General Ownership', 'First service at 500 km sets the wear baseline', 'The 500 km first service (oil change, bolt torque, chain setup) is the checkpoint that owners consistently say determines how the engine settles.', 'low', '0-500 km', 500, null, 'Metal-flecked first oil is normal; skipping the change is the real risk', 'Do the 500 km oil change on time, keep the bill, and get chain slack plus bolt torque checked.', 600, 1500, 10, 0, 'high', 'seed', null, now()),
  ('Royal Enfield', 'Meteor 350', null, 2021, 2022, 'Electrical', 'Tripper pod and cluster glitches on early batches', 'Early Meteor owners report the Tripper navigation pod going blank or rebooting and occasional battery-warning flickers, often fixed by connector or firmware attention.', 'medium', '5,000-15,000 km', null, null, 'Blank or rebooting Tripper pod, battery icon flicker, Bluetooth drops', 'Get connectors and firmware checked at the dealer and keep battery terminals clean and tight.', 0, 2500, 19, 5, 'low', 'seed', null, now()),
  ('Royal Enfield', 'Meteor 350', null, null, null, 'General Ownership', 'Handlebar buzz at sustained 100+ km/h', 'The Meteor cruises calmly below 100 km/h; above that riders report palm tingle and mirror blur on long highway stints.', 'low', null, null, '4,500-5,500 rpm', 'Mirror blur past 100 km/h, numb palms after long stretches', 'Use OEM bar-end weights or cushioned grips and cruise a notch below the buzz band on long days.', 0, 1200, 17, 4, 'medium', 'seed', null, now()),
  ('Royal Enfield', 'Meteor 350', null, null, null, 'Chain/Sprocket', 'Chain runs dry on highway tours', 'Touring owners report chain whine and accelerated wear when lubrication intervals stretch across long highway days.', 'low', '5,000-15,000 km', 10000, null, 'Dry or shiny links, whine at steady speed, tight spots when rotating the wheel', 'Lube every 500 km on tours (more often in rain) and check slack before multi-day rides.', 300, 900, 14, 3, 'medium', 'seed', null, now()),
  ('Royal Enfield', 'Meteor 350', null, null, null, 'Battery', 'Battery discharge when the bike sits for weeks', 'Weekend-only riders report weak cranking after the Meteor sits 1-2 weeks, especially with the Tripper pod and accessories drawing standby current.', 'low', '0-10,000 km', 5000, null, 'Sluggish first crank after a parked spell, clock/trip resets', 'Ride at least weekly or use a trickle charger; get the battery load-tested at the 5,000 km service.', 0, 4500, 16, 4, 'medium', 'seed', null, now()),
  ('Royal Enfield', 'Meteor 350', null, null, null, 'General Ownership', 'Stock seat comfort fades on 150+ km days', 'A common long-ride note: the rider perch feels great for an hour, then numbness sets in on full-day tours; many switch to touring seats.', 'low', 'Any', null, null, 'Numbness or hotspots after 150+ km stints, frequent standing on pegs', 'Plan a stop every 100-120 km or budget for a touring/gel seat if you ride long distances often.', 0, 6000, 13, 2, 'low', 'seed', null, now()),
  ('Royal Enfield', 'Hunter 350', null, null, null, 'Suspension', 'Stiff rear shocks over broken roads', 'The most repeated Hunter complaint: a firm rear setup that kicks over potholes and broken urban roads, especially riding solo.', 'medium', '0-8,000 km', 5000, null, 'Sharp kicks to the lower back on potholes, rear skipping over broken patches', 'Set preload to the softest step for solo riding and correct tyre pressures; consider quality aftermarket shocks if it still hurts.', 0, 9000, 44, 8, 'medium', 'seed', null, now()),
  ('Royal Enfield', 'Hunter 350', null, null, null, 'General Ownership', 'Footpeg buzz when held around 5,000 rpm', 'Riders report peg tingle when the engine sits near 5,000 rpm for long stretches; below that the J-series engine stays calm.', 'low', null, null, '4,500-5,500 rpm', 'Tingling pegs on sustained highway runs, mirror shimmer near the band', 'Short-shift to keep revs near 4,000 rpm when cruising and have mount bolts checked if buzz suddenly worsens.', 0, 800, 12, 3, 'low', 'seed', null, now()),
  ('Royal Enfield', 'Hunter 350', null, null, null, 'Chain/Sprocket', 'Chain grinding feel after monsoon city rides', 'Wet-season commuters report a gritty chain feel and surface rust specks when washing and lubing lag behind rain riding.', 'low', '3,000-9,000 km', 5000, null, 'Gritty feel through pegs at low speed, rust specks on links, squeak after rain', 'Rinse and re-lube the chain after sustained rain riding and keep slack in spec through the monsoon.', 300, 1000, 15, 4, 'medium', 'seed', null, now()),
  ('Royal Enfield', 'Hunter 350', null, 2022, 2023, 'Electrical', 'Horn and switchgear niggles on early batches', 'Some 2022-2023 build owners report weak or intermittent horns and inconsistent switch feel, usually sorted by dealer contact-cleaning or replacement.', 'low', '0-10,000 km', null, null, 'Horn cutting out or sounding weak, switches needing a double press', 'Have contacts cleaned/greased at service and log occurrences for a warranty swap if they repeat.', 0, 1200, 11, 2, 'low', 'seed', null, now()),
  ('Royal Enfield', 'Hunter 350', null, null, null, 'Tyres', 'Rear tyre squares off by 12-15k in city use', 'City-heavy Hunters commonly show a squared rear profile around 12,000-15,000 km, making tip-in feel vague before the tread is legally done.', 'low', '10,000-15,000 km', 15000, null, 'Flat centre band on the rear tyre, reluctance to lean, vague mid-corner feel', 'Keep pressures in spec, mix in open-road riding, and budget for a rear tyre around the 15,000 km checkpoint.', 3000, 5500, 13, 4, 'medium', 'seed', null, now()),
  ('Royal Enfield', 'Himalayan 450', null, null, null, 'Engine/Cooling', 'Heat and long fan cycles in slow traffic', 'The liquid-cooled Sherpa engine runs warm in crawling traffic; riders report high temperature bars, a hot right thigh, and the fan running long at idle.', 'medium', '0-10,000 km', 5000, null, 'Temperature bars climbing in jams, fan running continuously at idle, heat on the right thigh', 'Check coolant level at services, keep radiator fins clean (especially after off-road), and avoid long idling in jams.', 0, 1500, 38, 10, 'medium', 'seed', null, now()),
  ('Royal Enfield', 'Himalayan 450', null, 2023, 2024, 'Electrical', 'Early-production sensor and electrical niggles', 'Some first-batch owners report spurious warning lights and side-stand sensor cutoffs; dealers have addressed these with connector and software updates.', 'medium', '0-8,000 km', null, null, 'Random warning lights, engine cutting when shifting to first with the stand up', 'Get dealer software/connector updates applied and log each occurrence with date and odometer for warranty follow-up.', 0, 2000, 16, 5, 'low', 'seed', null, now()),
  ('Royal Enfield', 'Himalayan 450', null, null, null, 'Clutch', 'Notchy cold shifts when new, improving after first service', 'Owners commonly note clunky 1-2 shifts and a notchy cold gearbox in the first few hundred kilometres, settling after the first oil change.', 'low', '0-3,000 km', 500, null, 'Clunky first-to-second shifts cold, occasional false neutral in the first weeks', 'Do the first service oil change on schedule and have clutch lever free play set; re-check at 3,000 km if it persists.', 600, 1500, 14, 3, 'medium', 'seed', null, now()),
  ('Royal Enfield', 'Himalayan 450', null, null, null, 'Chain/Sprocket', 'Off-road use shortens chain life sharply', 'Dust and water crossings accelerate chain wear; trail-riding owners report tight spots and kinked links well before typical road-use life.', 'low', '8,000-18,000 km', 10000, null, 'Tight spots when spinning the rear wheel, kinked links after trail rides, fast slack growth', 'Clean and lube after every dusty or wet ride (300-500 km intervals off-road) and inspect sprocket teeth at 10,000 km.', 400, 4500, 12, 4, 'medium', 'seed', null, now()),
  ('Royal Enfield', 'Himalayan 450', null, null, null, 'General Ownership', 'Windscreen and cowl buzz near 5,500 rpm', 'A rattle from the screen/cowl area around 5,000-6,000 rpm is a recurring minor complaint, usually fixed with fastener checks or foam tape.', 'low', null, null, '5,000-6,000 rpm', 'Audible rattle from the front cowl at specific revs, loose screen fasteners', 'Check screen fasteners at service and add thin foam tape at contact points if the rattle returns.', 0, 500, 10, 2, 'low', 'seed', null, now()),
  ('Royal Enfield', 'Himalayan 450', null, null, null, 'Tyres', 'Stock dual-purpose tyres wear fast on tarmac touring', 'Owners who tour mostly on tarmac report the stock dual-purpose tyres squaring and losing wet grip earlier than road-biased rubber would.', 'low', '10,000-18,000 km', 15000, null, 'Centre wear on the rear, reduced wet-road confidence, block squirm on highways', 'Run load-correct pressures and plan tyre replacement around 15,000 km if your use is mostly road touring.', 8000, 14000, 11, 3, 'medium', 'seed', null, now()),
  ('Honda', 'CB350', null, null, null, 'Chain/Sprocket', 'Chain noise and early adjustment need', 'Riders log chain lash and adjustment needs earlier than expected, particularly in city use and monsoon months.', 'low', '3,000-9,000 km', 5000, null, 'Lash on throttle on/off transitions, clatter over bumps, frequent slack resets', 'Lube on Honda''s specified interval, keep slack in spec, and clean after rain riding.', 300, 1000, 23, 7, 'medium', 'seed', null, now()),
  ('Honda', 'CB350', null, null, null, 'Battery', 'Battery run-down with short-trip-only use', 'Short daily hops without longer runs leave some CB350 batteries undercharged, showing up as sluggish winter-morning starts.', 'low', '0-12,000 km', 10000, null, 'Sluggish cranking on cold mornings, weak horn at idle after short-trip weeks', 'Take a 30+ minute ride weekly or use a trickle charger; have charging voltage verified at service.', 0, 5200, 12, 3, 'medium', 'seed', null, now()),
  ('Honda', 'CB350', null, null, null, 'Brake Pads', 'Rear brake squeal reports', 'A minor but recurring note: rear brake squeal under light application, typically cleared by cleaning and deglazing at service.', 'low', '5,000-12,000 km', 10000, null, 'Squeal on light rear-brake application, dust caking around the caliper', 'Ask for pad deglaze and caliper cleaning at service; replace pads if squeal persists with low pad depth.', 400, 1500, 10, 2, 'low', 'seed', null, now()),
  ('Honda', 'CB350', null, null, null, 'General Ownership', 'BigWing network is sparser than mass-market brands', 'Ownership threads consistently flag longer distances to BigWing service points and occasional parts wait times outside metros.', 'low', 'Any', null, null, 'Long lead times for body panels or special-order parts, service centre 50+ km away', 'Plan services ahead, stock consumables (oil filter, pads) for your interval, and confirm parts before booking a slot.', null, null, 18, 5, 'medium', 'seed', null, now()),
  ('Honda', 'CB350', null, 2021, 2022, 'Electrical', 'Fuel gauge fluctuation on early units', 'A small set of early owners report fuel-bar readings jumping on slopes or after refuelling; dealers check the float and connections.', 'low', '0-10,000 km', null, null, 'Fuel bars jumping between readings, full-tank not showing full', 'Track range by trip meter and have the float/sender checked under warranty if readings stay erratic.', 0, 1500, 9, 2, 'low', 'seed', null, now()),
  ('KTM', 'Duke 390', null, null, null, 'Engine/Cooling', 'Radiator fan cycles frequently in dense traffic', 'Fan cycling and fast-climbing temperature readings in crawling traffic are the most common Duke 390 city observations; largely normal but worth monitoring.', 'medium', '0-20,000 km', 5000, null, 'Fan toggling on/off repeatedly in jams, temperature warnings on hot days, coolant smell after shutdown', 'Keep coolant topped to spec, get the radiator cleaned yearly, and avoid extended idling in gridlock.', 0, 2000, 35, 4, 'medium', 'seed', null, now()),
  ('KTM', 'Duke 390', null, null, null, 'Chain/Sprocket', 'Chain-sprocket kit wears by 18-25k with spirited riding', 'Hard-ridden Dukes commonly need a full chain-sprocket kit between 18,000-25,000 km; adjusters near the end of travel are the giveaway.', 'medium', '15,000-25,000 km', 20000, null, 'Adjuster marks near the end, hooked sprocket teeth, tight spots and lash together', 'Lube every 500 km, avoid pressure-washing the chain, and budget for a kit around the 20,000 km checkpoint.', 4500, 9000, 21, 5, 'medium', 'seed', null, now()),
  ('KTM', 'Duke 390', null, null, null, 'Brake Pads', 'Fast pad wear with aggressive city riding', 'Strong brakes plus aggressive use equals pads done by 6,000-12,000 km in many city-riding reports.', 'medium', '6,000-12,000 km', 10000, null, 'Growing lever travel, heavy black dust on the front wheel, metallic scrape when worn out', 'Inspect pads every 3,000 km, fit quality pads, and bed them properly after replacement.', 1200, 3200, 19, 4, 'medium', 'seed', null, now()),
  ('KTM', 'Duke 390', null, 2017, 2019, 'Electrical', 'TFT display fogging on early display-equipped gen', '2017-2019 Dukes with the first TFT dash have known condensation reports after rain; many were replaced under warranty.', 'low', '0-15,000 km', null, null, 'Condensation inside the TFT after rain or washing, display spots that fade as it dries', 'Park covered in monsoon and pursue warranty replacement early; out-of-warranty displays are expensive.', 0, 8000, 14, 2, 'low', 'seed', null, now()),
  ('KTM', 'Duke 390', null, 2013, 2016, 'Electrical', 'Regulator-rectifier failures on older generation', 'The 2013-2016 generation has a well-documented pattern of regulator/rectifier failures: batteries draining while riding and no-starts after highway runs.', 'high', '10,000-30,000 km', null, null, 'Battery draining while riding, flickering headlight, no-start right after a long highway run', 'Verify charging voltage (13.8-14.4V at 5,000 rpm) at services and fit an upgraded reg/rec if the original fails.', 2500, 6000, 27, 3, 'medium', 'seed', null, now()),
  ('KTM', 'Duke 390', null, null, null, 'Clutch', 'Clutch slip after sustained hard launches', 'Track-day and drag-happy owners report clutch slip past 15,000 km: revs rise without matching speed in higher gears.', 'medium', '15,000-30,000 km', 20000, null, 'RPM flare without acceleration in 4th-6th, burnt smell after hard runs', 'Use JASO MA2 oil only, keep free play in spec, and inspect plates at 20,000 km if you ride hard.', 3000, 8000, 12, 3, 'medium', 'seed', null, now()),
  ('KTM', 'Duke 390', null, null, null, 'General Ownership', 'Tank and seat buzz in the 7-8k rpm band', 'A high-frequency buzz through the tank and seat around 7,000-8,500 rpm is widely reported as engine character on long highway pulls.', 'low', null, null, '7,000-8,500 rpm', 'Numb inner thighs on long highway stints, buzzy pegs near the band', 'Treat mild buzz as character, but get engine mounts checked if it appears suddenly or worsens.', 0, 500, 13, 2, 'low', 'seed', null, now()),
  ('Triumph', 'Speed 400', null, null, null, 'General Ownership', 'First-service cost varies widely across cities', 'Owners comparing bills report the 500-1,000 km first service quoted differently across dealers and cities, creating spend uncertainty.', 'low', '500-2,000 km', 500, null, 'Quotes differing by thousands between dealers, unlisted add-ons on the estimate', 'Ask for an itemized estimate before work starts and keep bills to benchmark against other owners.', 2000, 4500, 20, 14, 'medium', 'seed', null, now()),
  ('Triumph', 'Speed 400', null, null, null, 'Engine/Cooling', 'Right-side heat from the exhaust in slow traffic', 'Riders report noticeable warmth on the right calf from the downpipe/cat area in crawling summer traffic; expected behaviour unless severe.', 'low', '0-8,000 km', 5000, null, 'Warm right calf in jams, heat shimmer off the downpipe at idle', 'Wear riding pants in summer traffic; have the dealer inspect if heat feels extreme or comes with a coolant warning.', 0, 500, 15, 4, 'low', 'seed', null, now()),
  ('Triumph', 'Speed 400', null, null, null, 'Chain/Sprocket', 'New-chain stretch needs an early adjustment', 'Multiple owners report chain slack growing quickly in the first 1,000-3,000 km as the new chain beds in, then stabilising.', 'low', '500-3,000 km', 3000, null, 'Slack audibly growing in the first weeks, light lash on throttle transitions', 'Check slack at 1,000 km rather than waiting for the service interval; it settles after the initial stretch.', 200, 600, 13, 3, 'medium', 'seed', null, now()),
  ('Triumph', 'Speed 400', null, 2023, 2024, 'Electrical', 'Minor switchgear and sensor niggles on launch batch', 'Early 2023-2024 units have scattered reports of switch feel issues and occasional warning lights, typically resolved with dealer updates.', 'low', '0-8,000 km', null, null, 'Occasional spurious warning light, switches needing a firm press', 'Apply dealer software updates and document each occurrence with date/odometer for warranty traction.', 0, 1500, 12, 3, 'low', 'seed', null, now()),
  ('Triumph', 'Speed 400', null, null, null, 'Suspension', 'Front fork feels soft for heavier riders', 'Riders above ~90 kg report noticeable front dive under hard braking and a soft feel two-up; lighter riders rarely mention it.', 'low', '0-10,000 km', null, null, 'Pronounced nose dive under hard braking, front wallowing two-up', 'Try firmer damping via heavier fork oil at a competent workshop if dive bothers you; ride within limits meanwhile.', 0, 3000, 9, 2, 'low', 'seed', null, now())
